package vn.edu.library.ui;

import vn.edu.library.data.Database;
import vn.edu.library.domain.UserSession;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.math.BigDecimal;
import java.sql.*;

public final class ViolationsPanel extends JPanel {
    private final UserSession session;
    private final JTextField search=new JTextField(24);
    private final JLabel status=new JLabel(" ");
    private final DefaultTableModel model=new DefaultTableModel(){@Override public boolean isCellEditable(int r,int c){return false;}};
    private final JTable table=new JTable(model);
    public ViolationsPanel(UserSession session){this.session=session;setLayout(new BorderLayout(0,16));setBackground(UiStyle.CANVAS);setBorder(new EmptyBorder(27,30,24,30));add(header(),BorderLayout.NORTH);table.setRowHeight(33);table.setAutoCreateRowSorter(true);table.setFillsViewportHeight(true);JScrollPane sc=new JScrollPane(table);sc.setBorder(BorderFactory.createLineBorder(new Color(229,233,240)));add(sc,BorderLayout.CENTER);status.setForeground(UiStyle.MUTED);add(status,BorderLayout.SOUTH);load();}
    private JComponent header(){JPanel h=new JPanel(new BorderLayout(0,16));h.setOpaque(false);JPanel t=new JPanel();t.setOpaque(false);t.setLayout(new BoxLayout(t,BoxLayout.Y_AXIS));JLabel title=new JLabel("Vi phạm – tiền phạt và bồi thường");title.setFont(title.getFont().deriveFont(Font.BOLD,25f));JLabel sub=new JLabel("Ghi nhận quá hạn, hư hỏng, mất sách và nhận thanh toán từng phần.");sub.setForeground(UiStyle.MUTED);t.add(title);t.add(Box.createVerticalStrut(5));t.add(sub);h.add(t,BorderLayout.NORTH);search.putClientProperty("JTextField.placeholderText","Mã độc giả, tên độc giả, sách, loại vi phạm");JButton find=new JButton("Tìm kiếm"),refresh=new JButton("Làm mới"),pay=new JButton("Ghi nhận thanh toán");pay.setBackground(UiStyle.BLUE);pay.setForeground(Color.WHITE);find.addActionListener(e->load());refresh.addActionListener(e->{search.setText("");load();});search.addActionListener(e->load());pay.addActionListener(e->collect());JPanel c=new JPanel(new FlowLayout(FlowLayout.LEFT,7,0));c.setOpaque(false);c.add(search);c.add(find);c.add(refresh);c.add(pay);h.add(c,BorderLayout.SOUTH);return h;}
    private void load(){String term=search.getText().trim();String sql="SELECT v.violation_id AS 'Mã vi phạm',m.member_code AS 'Mã độc giả',m.full_name AS 'Độc giả',b.title AS 'Sách',v.violation_type AS 'Loại',v.assessed_amount AS 'Phải thu (VND)',v.paid_amount AS 'Đã thu (VND)',v.assessed_amount-v.paid_amount AS 'Còn nợ (VND)',v.violation_status AS 'Trạng thái',v.assessed_at AS 'Ngày ghi nhận' FROM violations v JOIN loan_items li ON li.loan_item_id=v.loan_item_id JOIN loans l ON l.loan_id=li.loan_id JOIN school_members m ON m.member_id=l.member_id JOIN book_copies cp ON cp.copy_id=li.copy_id JOIN books b ON b.book_id=cp.book_id WHERE (?='' OR m.member_code LIKE ? OR m.full_name LIKE ? OR b.title LIKE ? OR v.violation_type LIKE ?) ORDER BY v.assessed_at DESC";try(Connection c=Database.getConnection();PreparedStatement q=c.prepareStatement(sql)){String p="%"+term+"%";q.setString(1,term);for(int i=2;i<=5;i++)q.setString(i,p);try(ResultSet rs=q.executeQuery()){ResultSetMetaData md=rs.getMetaData();model.setRowCount(0);model.setColumnCount(0);for(int i=1;i<=md.getColumnCount();i++)model.addColumn(md.getColumnLabel(i));while(rs.next()){Object[] a=new Object[md.getColumnCount()];for(int i=1;i<=a.length;i++)a[i-1]=rs.getObject(i);model.addRow(a);}}status.setText("Đang hiển thị "+model.getRowCount()+" trường hợp vi phạm.");}catch(Exception ex){model.setRowCount(0);status.setText("Không tải được vi phạm: "+ex.getMessage());}}
    private void collect(){int view=table.getSelectedRow();if(view<0){message("Chọn khoản cần thu trước.",JOptionPane.INFORMATION_MESSAGE);return;}int row=table.convertRowIndexToModel(view);long id=Long.parseLong(model.getValueAt(row,0).toString());BigDecimal due=new BigDecimal(model.getValueAt(row,7).toString());if(due.signum()<=0){message("Khoản này đã thanh toán đủ.",JOptionPane.INFORMATION_MESSAGE);return;}String entered=JOptionPane.showInputDialog(this,"Còn nợ "+due.toPlainString()+" đồng. Nhập số tiền nhận:",due.toPlainString());if(entered==null)return;BigDecimal amount;try{amount=new BigDecimal(entered.trim());if(amount.signum()<=0||amount.compareTo(due)>0)throw new NumberFormatException();}catch(Exception ex){message("Số tiền phải lớn hơn 0 và không vượt quá số còn nợ.",JOptionPane.WARNING_MESSAGE);return;}try(Connection c=Database.getConnection()){c.setAutoCommit(false);try{BigDecimal current;try(PreparedStatement q=c.prepareStatement("SELECT assessed_amount-paid_amount FROM violations WHERE violation_id=? AND violation_status IN ('UNPAID','PARTIALLY_PAID') FOR UPDATE")){q.setLong(1,id);try(ResultSet rs=q.executeQuery()){if(!rs.next())throw new IllegalArgumentException("Khoản vi phạm đã được xử lý.");current=rs.getBigDecimal(1);}}if(amount.compareTo(current)>0)throw new IllegalArgumentException("Số tiền còn nợ vừa thay đổi. Tải lại danh sách và thử lại.");long staff=staffId(c);String receipt="VP-"+System.currentTimeMillis();try(PreparedStatement q=c.prepareStatement("INSERT INTO violation_payments(violation_id,amount,receipt_number,received_by) VALUES(?,?,?,?)")){q.setLong(1,id);q.setBigDecimal(2,amount);q.setString(3,receipt);q.setLong(4,staff);q.executeUpdate();}String nextStatus=amount.compareTo(current)==0?"PAID":"PARTIALLY_PAID";try(PreparedStatement q=c.prepareStatement("UPDATE violations SET paid_amount=paid_amount+?,violation_status=? WHERE violation_id=?")){q.setBigDecimal(1,amount);q.setString(2,nextStatus);q.setLong(3,id);q.executeUpdate();}c.commit();load();message("Đã thu "+amount.toPlainString()+" đồng. Biên lai: "+receipt+".",JOptionPane.INFORMATION_MESSAGE);}catch(Exception ex){c.rollback();throw ex;}finally{c.setAutoCommit(true);}}catch(Exception ex){message("Không ghi nhận được thanh toán: "+ex.getMessage(),JOptionPane.ERROR_MESSAGE);}}
    private long staffId(Connection c)throws SQLException{try(PreparedStatement q=c.prepareStatement("SELECT staff_id FROM accounts WHERE account_id=? AND staff_id IS NOT NULL")){q.setLong(1,session.accountId());try(ResultSet r=q.executeQuery()){if(!r.next())throw new SQLException("Tài khoản chưa liên kết nhân viên.");return r.getLong(1);}}}
    private void message(String s,int t){JOptionPane.showMessageDialog(this,s,"Vi phạm",t);}
}
